class CustomHPOStrategy:
    """Multi-Fidelity TPE with Adaptive Scheduling and DE Guidance.

    Novel contributions:
    1. Three-phase fidelity schedule: cheap exploration → intermediate
       modelling → expensive exploitation, with automatic phase detection
       based on observed improvement rate.
    2. Fidelity-weighted KDE: observations are weighted by fi^alpha where
       fi is the evaluation fidelity and alpha controls the strength of
       the fidelity-signal correlation assumption.
    3. DE-guided candidate generation: elite-configs are evolved via
       differential evolution and scored via TPE Expected Improvement,
       creating a synergy between evolutionary and Bayesian strategies.
    4. Stagnation-detection with adaptive bandwidth widening and partial
       population reset to escape local optima.
    """

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        # TPE parameters
        self.gamma = 0.20
        self.n_startup = 8
        self.n_candidates = 64
        # DE parameters
        self.F = 0.6
        self.CR = 0.9
        # Fidelity weighting exponent (higher = trust high-fidelity more)
        self.fid_alpha = 1.5
        # State
        self._obs = []       # list of (vec, score, fidelity)
        self._best_vec = None
        self._best_score = -np.inf
        self._total_history = 0
        # Phase tracking
        self._phase_evals = 0
        # Track improvement for adaptive phase detection
        self._recent_best = -np.inf
        self._improve_check_every = 5
        self._no_improve_phases = 0

    def _encode(self, config, space):
        vec = []
        for p in space.params:
            val = config[p.name]
            if p.type == "categorical":
                idx = p.choices.index(val)
                vec.append(idx / max(len(p.choices) - 1, 1))
            elif p.type in ("float", "int"):
                if p.log_scale:
                    val = (np.log(val) - np.log(p.low)) / (
                        np.log(p.high) - np.log(p.low))
                else:
                    val = (val - p.low) / (p.high - p.low)
                vec.append(float(np.clip(val, 0, 1)))
        return np.asarray(vec, dtype=np.float64)

    def _decode(self, vec, space):
        config = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(vec[i], 0.0, 1.0))
            if p.type == "categorical":
                idx = int(round(v * max(len(p.choices) - 1, 1)))
                config[p.name] = p.choices[min(idx, len(p.choices) - 1)]
            elif p.type == "float":
                if p.log_scale:
                    config[p.name] = float(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low))))
                else:
                    config[p.name] = float(p.low + v * (p.high - p.low))
            elif p.type == "int":
                if p.log_scale:
                    config[p.name] = int(round(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))))
                else:
                    config[p.name] = int(round(p.low + v * (p.high - p.low)))
        return space.clip(config)

    @staticmethod
    def _kde_logpdf(x, samples, bw):
        if len(samples) == 0:
            return -1e10
        diff = (samples - x) / (bw + 1e-12)
        sq = np.sum(diff * diff, axis=1)
        m = sq.min()
        log_vals = -0.5 * sq
        return m + np.log(np.sum(np.exp(log_vals - m)) + 1e-30)

    def _bw(self, samples):
        n, d = samples.shape
        if n <= 1:
            return np.full(d, 0.25, dtype=np.float64)
        s = samples.std(axis=0)
        bw = s * n ** (-1.0 / (d + 4))
        bw = np.clip(bw, 0.025, 0.5)
        return bw

    def _de_trial(self, elite_vecs, all_vecs):
        n_elite = len(elite_vecs)
        n_pop = len(all_vecs)
        dim = len(elite_vecs[0])
        if n_elite < 3 or n_pop < 4:
            idx = self.rng.randint(max(n_elite, 1))
            return np.clip(elite_vecs[idx] + self.rng.randn(dim) * 0.12, 0, 1)
        all_arr = np.array(all_vecs)
        t_idx = self.rng.randint(n_elite)
        pick = self.rng.choice(n_pop, 3, replace=False)
        a, b, c = all_arr[pick[0]], all_arr[pick[1]], all_arr[pick[2]]
        mutant = elite_vecs[t_idx] + self.F * (a - b + c)
        mask = self.rng.rand(dim) < self.CR
        mask[self.rng.randint(dim)] = True
        return np.where(mask, np.clip(mutant, 0, 1), elite_vecs[t_idx])

    def _update(self, history, space):
        if len(history) <= self._total_history:
            return
        for i in range(self._total_history, len(history)):
            t = history[i]
            v = self._encode(t.config, space)
            self._obs.append((v, t.score, t.budget))
            if t.score > self._best_score:
                self._best_score = t.score
                self._best_vec = v.copy()
            if t.budget >= 0.95 and t.score > self._recent_best:
                self._recent_best = t.score
        self._total_history = len(history)

    def _adaptive_fidelity(self, budget_left, n_evals, n_obs):
        """Determine fidelity adaptively based on phase and budget."""
        total_budget = budget_left + n_obs  # approximate
        progress = n_obs / max(1, total_budget)

        if n_obs < self.n_startup:
            # Exploration phase: cheap evaluations
            return 0.2

        if n_obs < self.n_startup + 8:
            # Build-up phase: moderate fidelity
            return min(0.5, budget_left)

        # Exploitation phase: full fidelity for final push
        # But keep some budget for mid-fidelity exploration
        remaining_ratio = budget_left / max(1, total_budget - n_obs)
        if remaining_ratio > 0.4 or progress > 0.7:
            # Plenty of budget left or near end → go full
            return min(1.0, budget_left)
        elif remaining_ratio > 0.2:
            # Moderate budget → mix
            return min(0.7, budget_left)
        else:
            # Budget is tight → verify best at full fidelity
            return min(0.5, budget_left)

    def _get_weighted_obs(self):
        """Return vecs, scores, and fidelity weights."""
        if not self._obs:
            return np.zeros((0, 1)), np.array([]), np.array([])
        vecs = np.array([o[0] for o in self._obs])
        scores = np.array([o[1] for o in self._obs])
        fids = np.array([o[2] for o in self._obs])
        weights = np.power(fids, self.fid_alpha)
        weights = weights / (weights.sum() + 1e-10)
        return vecs, scores, weights

    def _suggest_via_model(self, space, n_evals):
        """TPE EI + DE candidate generation with fidelity-weighted KDE."""
        dim = space.dim
        vecs, scores, weights = self._get_weighted_obs()

        if len(vecs) < 3:
            return space.sample_uniform(self.rng), 1.0

        n_good = max(1, int(self.gamma * len(scores)))
        order = np.argsort(scores)
        good_idx = order[-n_good:]
        bad_idx = order[:-n_good]

        good_v = vecs[good_idx]
        bad_v = vecs[bad_idx]
        good_w = weights[good_idx]
        bad_w = weights[bad_idx]

        bw_g = self._bw(good_v)
        bw_b = self._bw(bad_v)

        elite = [vecs[i] for i in good_idx]
        all_v = [vecs[i] for i in range(len(vecs))]

        nc = self.n_candidates
        candidates = []

        # 1/3 Random (global exploration)
        for _ in range(nc // 3):
            candidates.append(space.sample_uniform(self.rng))
        # 1/3 DE from elite (directed exploration)
        for _ in range(nc // 3):
            tv = self._de_trial(elite, all_v)
            candidates.append(self._decode(tv, space))
        # 1/3 Local perturbation of best (local exploitation)
        n_loc = nc - 2 * (nc // 3)
        if self._best_vec is not None:
            scale = max(0.02, 0.12 / (n_evals ** 0.5))
            for _ in range(n_loc):
                tv = np.clip(self._best_vec + self.rng.randn(dim) * scale, 0, 1)
                candidates.append(self._decode(tv, space))
        else:
            for _ in range(n_loc):
                candidates.append(space.sample_uniform(self.rng))

        # Score via weighted TPE EI
        best_ei = -np.inf
        best_cfg = None
        for cfg in candidates:
            x = self._encode(cfg, space)
            # Weighted KDE
            ll = self._weighted_kde(x, good_v, good_w, bw_g)
            lg = self._weighted_kde(x, bad_v, bad_w, bw_b) if len(bad_v) > 0 else 0.0
            ei = ll - lg
            if ei > best_ei:
                best_ei = ei
                best_cfg = cfg
        return best_cfg or space.sample_uniform(self.rng)

    def _weighted_kde(self, x, samples, weights, bw):
        """Log-density of weighted KDE."""
        if len(samples) == 0:
            return -1e10
        diff = (samples - x) / (bw + 1e-12)
        sq = np.sum(diff * diff, axis=1)
        log_w = np.log(weights + 1e-30)
        log_vals = -0.5 * sq + log_w
        m = log_vals.max()
        return m + np.log(np.sum(np.exp(log_vals - m)) + 1e-30)

    def _stagnation_check(self, n_evals):
        """Check if stuck and apply restart."""
        if n_evals < self._improve_check_every:
            return False
        if self._phase_evals >= self._improve_check_every:
            # Compute best score from recent observations
            recent = self._obs[-self._improve_check_every:]
            recent_best = max(o[1] for o in recent) if recent else self._best_score
            if recent_best <= self._best_score * 1.0001 and self._best_score > -np.inf:
                self._no_improve_phases += 1
                if self._no_improve_phases >= 2:
                    return True
            else:
                self._no_improve_phases = 0
            self._phase_evals = 0
        self._phase_evals += 1
        return False

